// Build-time access to books.yaml and to the generated reading pages.
import { getCollection } from 'astro:content';

// __BOOKS__ and __COVER_FILES__ are set in astro.config.mjs from books.yaml and public/books/.
export const books = [...__BOOKS__].sort((a, b) => a.number - b.number);

export function bookBySlug(slug) {
  const book = books.find((item) => item.slug === slug);
  if (!book) throw new Error(`No book with slug ${slug} in books.yaml`);
  return book;
}

// The cover files are generated by the export script and are not in git.
export function coverUrl(slug) {
  return __COVER_FILES__[slug] ? `/books/${slug}/thumb-400x640.png` : null;
}

export function fullCoverUrl(slug) {
  return __COVER_FILES__[slug] ? `/books/${slug}/cover-1600x2560.png` : null;
}

// Chapter pages for a book: the numbered files written by the export script.
export async function chapterPages(slug) {
  const entries = await getCollection('docs', ({ id }) => {
    const [folder, file] = id.split('/');
    return folder === slug && /^\d{2}-/.test(file ?? '');
  });
  return entries
    .map((entry) => ({ id: entry.id, title: entry.data.title, order: entry.data.sidebar?.order ?? 0 }))
    .sort((a, b) => a.order - b.order);
}

// A book is readable online only when the author has allowed it and its pages were exported.
export async function isReadableOnline(slug) {
  const book = bookBySlug(slug);
  if (!book.online) return false;
  return (await chapterPages(slug)).length > 0;
}
